// TH14 v1.00b Stage 4 wave 2 (th14_s4_w02).
// Entry: st04.ecl.txt::MainSub00 976-998. Merged group: GirlD01 at source frames
// 0/480, ECir00 pairs at 180..280, ECir00M row at 540..660 (schedule ends 680).
// Card frame 0 = phase segment start; wave_pattern waits OPENING_BUFFER first, so
// source frame 0 sits at card frame 120 (+1 for the pattern task's first run).
// Closures: GirlD01 (+GirlD01_at), ECir00 (+ECir00_at).
//
// Approximations carried over from the shared rules: chapters/drops/visual ANM/flagSet
// are omitted; the ANIM(a=1) birth displacement position -= 4*velocity is kept.

const TIME_LIMIT: int = 2424;
const OPENING_BUFFER: int = 120;

// Source ECir00_at uses the emitter sprite (etSprite(0,20,3)) for its Line; the target
// laser has its own texture, so only the source color is kept.
const LASER_COLOR: int = 3;

// ---- GirlD01_at (697-741) ----
// wait(60); A = rank+1 rounds; per round B=20deg, C=8, D=15 pairs, gap 4/3/2/1,
// C += 10, B *= 0.98. Each pair fires two bullets (offset radius +C then -C):
//   etOffsetRad(0, B*RANDF2, C) / etAngle(0, 90deg + RANDF2*6deg) /
//   etSpeed(0, 1 + RANDF*1.5) / etOn, then the same at -C.
// etSprite(0,8,6) = TH14_RICE color 6; etEx(...,2,1) is ANIM(a=1): birth position
// retreats 4*velocity along the bullet angle (kept, birth ANM itself omitted).
async sub girld01_at() {
    var rank: int = global(GVAR_RANK);
    var rounds: int = rank + 1;          // diffI($A, 1, 2, 3, 4)
    var gap: int = 4;                    // wait([-1]): E4 N3 H2 L1
    if rank == RANK_NORMAL { gap = 3; }
    else if rank == RANK_HARD { gap = 2; }
    else if rank >= RANK_LUNATIC { gap = 1; }
    wait(60);
    for n in 0..rounds {
        var b: fx = 20fx;                // %B = 0.349066rad
        var c: fx = 8fx;                 // %C
        for d in 0..15 {
            var r1: int = rand(65536);
            var oa: angle = (((b * ((r1 - 32768) as fx / 32768)) as int) as angle);
            var r2: int = rand(65536);
            var a1: angle = 90deg + (((6fx * ((r2 - 32768) as fx / 32768)) as int) as angle);
            var r3: int = rand(65536);
            var s1: fx = 1fx + (((r3 - 32768) as fx / 65536 + 0.5fx) * 1.5fx);
            _ = fire(TH14_RICE, 6, $self_x + c * cos(oa) - 4fx * s1 * cos(a1),
                     $self_y + c * sin(oa) - 4fx * s1 * sin(a1), s1, a1, none, none);
            var r4: int = rand(65536);
            var ob: angle = (((b * ((r4 - 32768) as fx / 32768)) as int) as angle);
            var r5: int = rand(65536);
            var a2: angle = 90deg + (((6fx * ((r5 - 32768) as fx / 32768)) as int) as angle);
            var r6: int = rand(65536);
            var s2: fx = 1fx + (((r6 - 32768) as fx / 65536 + 0.5fx) * 1.5fx);
            _ = fire(TH14_RICE, 6, $self_x + (0fx - c) * cos(ob) - 4fx * s2 * cos(a2),
                     $self_y + (0fx - c) * sin(ob) - 4fx * s2 * sin(a2), s2, a2, none, none);
            c = c + 10fx;
            b = b * 0.98fx;
            wait(gap);
        }
    }
}

// ---- GirlD01 (673-695) ----
// setHurtbox(32,32) -> r=16, setHitbox(24,24) -> r=12. moveVel(pi/2, 1.4) then
// moveSpeedTime(60,1,0); at t120 moveSpeedTime(80,1,1.0); t260 loop wait(1000).
async sub girld01() {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    move_vel(0, 90deg, 1.4fx, EASE_LINEAR);
    move_speed(60, 0fx, EASE_QUAD_IN);
    spawn girld01_at();
    wait(120);
    move_speed(80, 1fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1000); }
}

// ---- ECir00_at (47-146) ----
// wait(10); laserNew(0, 0, L, 0, 14) with L=128/128/144/160 and etSpeed 2.7/3.5/4.5/5.0,
// then per burst: etAngle(0, ANGLE_PLAYER, 0); laserOn(0); on Normal+ two emitter bursts
// (etNew(1) mode 8 random, count 1/3/5/5, and mode 1 fan 2 ways), then wait 600/50/10/8.
// bursts = diffI($A, 1,1,1,8).
// Line judgement is [0.1L, 0.9L] with half height w/4 = 3.5 (w=14) -> target width 7;
// modelled as a 0.8L rod growing from the origin and flying at the source etSpeed
// (laser_approx, same approximation as the TH14 Line cards).
async sub ecir00_at() {
    var rank: int = global(GVAR_RANK);
    var rod: fx = 102.4fx;               // 0.8 * 128 (E/N)
    var speed: fx = 2.7fx;               // etSpeed(0, s, s)
    var bursts: int = 1;                 // diffI($A, 1, 1, 1, 8)
    var gap: int = 600;                  // wait([-1]): E600 N50 H10 L8
    var count: int = 1;                  // etCount(1, [-1], 1): E1 N3 H5 L5
    var amp: fx = 2.0fx;                 // etSpeed(1, 1.0, [-1]): E2 N2.5 H2.5 L3
    if rank == RANK_NORMAL {
        speed = 3.5fx; gap = 50; count = 3; amp = 2.5fx;
    } else if rank == RANK_HARD {
        rod = 115.2fx; speed = 4.5fx; gap = 10; count = 5; amp = 2.5fx;
    } else if rank >= RANK_LUNATIC {
        rod = 128fx; speed = 5.0fx; bursts = 8; gap = 8; count = 5; amp = 3.0fx;
    }
    wait(10);
    for i in 0..bursts {
        var h: int = laser(LASER_COLOR, $self_x, $self_y, aim_player(), 0fx, 7fx, 0, 600, 0);
        lz_speed(h, speed, rod);
        if rank >= RANK_NORMAL {
            // etNew(1); etAim(1,8); etSprite(1,4,8); mode 8: per bullet angle then speed.
            var aim: angle = aim_player();
            for k in 0..count {
                var r1: int = rand(65536);
                var a: angle = aim + (((18fx * ((r1 - 32768) as fx / 32768)) as int) as angle);
                var r2: int = rand(65536);
                var sp: fx = 1fx + (((r2 - 32768) as fx / 65536 + 0.5fx) * amp);
                _ = fire(TH14_BALL, 8, $self_x - 4fx * sp * cos(a), $self_y - 4fx * sp * sin(a),
                         sp, a, none, none);
            }
            // etNew(1); etAim(1,1); etSprite(1,4,8); etCount(1,2,1); etAngle(...,3deg);
            // etSpeed(1,2,2): mode 1 fan, F(2,0)=+1.5deg, F(2,1)=-1.5deg, speed 2.
            var fan: angle = aim_player();
            var ap: angle = fan + 1.5deg;
            _ = fire(TH14_BALL, 8, $self_x - 8fx * cos(ap), $self_y - 8fx * sin(ap),
                     2fx, ap, none, none);
            var am: angle = fan - 1.5deg;
            _ = fire(TH14_BALL, 8, $self_x - 8fx * cos(am), $self_y - 8fx * sin(am),
                     2fx, am, none, none);
        }
        wait(gap);
    }
}

// ---- ECir00 (12-45) ----
// setHurtbox(24,24) -> r=12, setHitbox(16,16) -> r=8. %A = +1, or -1 for enmCreateM.
// movePosRel(-192*A, 0) then moveBezierRel(120, 256A,-30, 160A,128, 0,0); at t120
// spawn ECir00_at and start moveBezierRel(120, 0,0, -220A,192, -200A,-228).
// moveBezierRel stores normalized-time Hermite tangents, so the target slots take the
// same numbers; both layers are REL-only, ABS stays at the birth point -> absolute
// position = birth + REL, written each frame with move_to(0).
async sub ecir00(dir: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    var sx: fx = $self_x;
    var sy: fx = $self_y;
    var d: fx = dir as fx;
    hermite_start(0, 0fx - 192fx * d, 160fx * d, 256fx * d, 0fx, 120);
    hermite_start(1, 0fx, 128fx, 0fx - 30fx, 0fx, 120);
    move_to(0, sx - 192fx * d, sy, EASE_LINEAR);
    for k in 1..121 {
        wait(1);
        move_to(0, sx + hermite_value(0), sy + hermite_value(1), EASE_LINEAR);
    }
    spawn ecir00_at();
    hermite_start(0, 160fx * d, 0fx - 220fx * d, 0fx, 0fx - 200fx * d, 120);
    hermite_start(1, 128fx, 192fx, 0fx, 0fx - 228fx, 120);
    for k2 in 1..121 {
        wait(1);
        move_to(0, sx + hermite_value(0), sy + hermite_value(1), EASE_LINEAR);
    }
    loop { wait(1000); }
}

// ---- MainSub00 976-998 ----
// GirlD01 (0,-32) at source 0; 3x [ECir00 then ECir00M at (0,0), 20 frames apart] at
// 180..300; GirlD01 (96,-32) at 480; 7x ECir00M at x=0,10..60 every 20 frames (540..680).
async sub wave_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -32fx, 800, 0, 0, 0, girld01());
    wait(180);
    for i in 0..3 {
        _ = spawn_enemy(0fx, 0fx, 150, 0, 0, 0, ecir00(1));
        wait(20);
        _ = spawn_enemy(0fx, 0fx, 150, 0, 0, 0, ecir00(-1));
        wait(20);
    }
    wait(180);
    _ = spawn_enemy(96fx, -32fx, 800, 0, 0, 0, girld01());
    wait(60);
    var ax: fx = 0fx;
    for j in 0..7 {
        _ = spawn_enemy(ax, 0fx, 150, 0, 0, 0, ecir00(-1));
        wait(20);
        ax = ax + 10fx;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

